def nth_integer_with_k_one_bits(n,k):
    from math import comb
    answer=0
    for position in range(49,-1,-1):
        without=comb(position,k) if 0<=k<=position else 0
        if n>without:
            n-=without;answer|=1<<position;k-=1
            if k==0:break
    return answer

